let currentIndex = 0;

function changeLogo() {
    const logo = document.getElementById('header_logo');
    const logo2 = document.getElementById('footer_img');

    if (logo) {
        logo.style.transition = 'opacity 0.5s';
        logo.style.opacity = 0;

        // Use setTimeout to change image smoothly
        setTimeout(() => {
            currentIndex = (currentIndex + 1) % images.length;
            logo.src = images[currentIndex];
            logo.style.opacity = 1;
        }, 500);
    }

    if (logo2) {
        logo2.style.transition = 'opacity 0.5s';
        logo2.style.opacity = 0;

        setTimeout(() => {
            logo2.src = images[currentIndex];
            logo2.style.opacity = 1;
        }, 500);
    }
}

// Change image every 2 seconds
const logoInterval = setInterval(changeLogo, 2000);

// Optional: Pause rotation on hover to improve user experience
const pauseRotation = () => clearInterval(logoInterval);
const resumeRotation = () => setInterval(changeLogo, 2000);

const headerLogo = document.getElementById('header_logo');
const footerLogo = document.getElementById('footer_img');

if (headerLogo) {
    headerLogo.addEventListener('mouseenter', pauseRotation);
    headerLogo.addEventListener('mouseleave', resumeRotation);
}

if (footerLogo) {
    footerLogo.addEventListener('mouseenter', pauseRotation);
    footerLogo.addEventListener('mouseleave', resumeRotation);
